class A:
 @staticmethod
 def __repr__(): return "static"
 @classmethod
 def __str__(cls): return cls.__name__
print(repr(A()),str(A()))

class A:
 def __init__(self,n): self.n=n
 @property
 def __str__(self):
  print("binding")
  def render(): return "n="+str(self.n)
  return render
print("start",A(7),"end")

class D:
 def __get__(self,instance,owner):
  print(owner.__name__)
  def render(): return str(instance.n)
  return render
class A:
 __repr__=D()
 def __init__(self,n): self.n=n
class B(A): pass
print(repr(B(8)))

class Render:
 def __call__(self): return "callable"
class A:
 __str__=Render()
print(A())

events=[]
class A:
 def __str__(self):
  events.append(3)
  return "a"
def mark(n):
 events.append(n)
 return A()
print(mark(1),mark(2))
print(events[0],events[1],events[2],events[3])

class A:
 def __str__(self):
  print("inner")
  return "outer"
print("start",A(),"end")

class A:
 def __str__(self):
  print("inner")
  return "outer"
print(A(),A())

class A:
 def __str__(self): raise ValueError("bad")
try: print("start",A(),"end")
except ValueError: print("caught")

class A:
 def __str__(self): return 7
try: print("start",A())
except TypeError: print("caught")

class A:
 @property
 def __str__(self): raise AttributeError("bad")
try: print("start",A())
except AttributeError: print("caught")

class A:
 def __repr__(self): return "a"
class B:
 def __str__(self): return "b:"+repr(A())
print(B())

class A:
 def __repr__(self):
  try: return "value"
  finally: print("finally")
print(repr(A()))

class A:
 def __str__(self): raise
try:
 raise ValueError("original")
except ValueError:
 try: print("start",A())
 except ValueError as error: print(str(error))
 finally: print("finally")

class A:
